//! Integration tests for FFprobe metadata parsing.
//!
//! Fixtures are generated by `tests/fixtures/generate.sh`. These tests assert
//! model behavior, not FFprobe log wording.

use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, Instant};

use rossresscut::application::{Application, OpenState};
use rossresscut::domain::media::{AudioStream, MediaFile, MediaStream, VideoStream};
use rossresscut::domain::time::Duration as MediaDuration;
use rossresscut::media::ffprobe::{self, ProbeError};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name)
}

fn probe_fixture(name: &str) -> MediaFile {
    let path = fixture(name);
    match ffprobe::probe(&path) {
        Ok(media) => media,
        Err(error) => panic!("failed to probe {}: {error}", path.display()),
    }
}

fn first_video(media: &MediaFile) -> &VideoStream {
    let Some(video) = media.streams.iter().find_map(|stream| match stream {
        MediaStream::Video(video) => Some(video),
        _ => None,
    }) else {
        panic!("expected a video stream in {}", media.path.display());
    };
    video
}

fn first_audio(media: &MediaFile) -> &AudioStream {
    let Some(audio) = media.streams.iter().find_map(|stream| match stream {
        MediaStream::Audio(audio) => Some(audio),
        _ => None,
    }) else {
        panic!("expected an audio stream in {}", media.path.display());
    };
    audio
}

fn count_audio(media: &MediaFile) -> usize {
    media
        .streams
        .iter()
        .filter(|stream| matches!(stream, MediaStream::Audio(_)))
        .count()
}

fn count_subtitles(media: &MediaFile) -> usize {
    media
        .streams
        .iter()
        .filter(|stream| matches!(stream, MediaStream::Subtitle(_)))
        .count()
}

#[test]
fn probes_common_containers_and_codecs() {
    let cases = [
        ("sample.mp4", "mov,mp4", "h264", "aac"),
        ("sample.mkv", "matroska", "h264", "aac"),
        ("sample.wmv", "asf", "wmv2", "wmav2"),
        ("sample.avi", "avi", "mpeg4", "pcm_s16le"),
        ("sample.ts", "mpegts", "h264", "aac"),
    ];

    for (name, expected_format, expected_video_codec, expected_audio_codec) in cases {
        let media = probe_fixture(name);

        assert!(
            media.format.name.contains(expected_format),
            "{name}: unexpected container {:?}",
            media.format.name
        );
        let Some(duration) = media.duration else {
            panic!("{name}: expected a container duration");
        };
        assert!(
            duration >= MediaDuration::from_micros(500_000)
                && duration <= MediaDuration::from_micros(3_000_000),
            "{name}: unexpected duration {duration}"
        );

        let video = first_video(&media);
        assert_eq!(
            video.info.codec_name.as_deref(),
            Some(expected_video_codec),
            "{name}: unexpected video codec"
        );
        assert_eq!(video.width, Some(160), "{name}: unexpected width");
        assert_eq!(video.height, Some(120), "{name}: unexpected height");
        assert!(video.frame_rate.is_some(), "{name}: expected a frame rate");
        assert!(
            video.info.time_base.is_some(),
            "{name}: expected a video time base"
        );

        let audio = first_audio(&media);
        assert_eq!(
            audio.info.codec_name.as_deref(),
            Some(expected_audio_codec),
            "{name}: unexpected audio codec"
        );
        assert!(
            audio.sample_rate.is_some(),
            "{name}: expected a sample rate"
        );
        assert!(audio.channels.is_some(), "{name}: expected channel count");
    }
}

#[test]
fn probes_multiple_audio_streams_chapters_and_subtitles() {
    let media = probe_fixture("sample.mkv");

    assert_eq!(count_audio(&media), 2);
    assert_eq!(count_subtitles(&media), 1);
    assert_eq!(media.chapters.len(), 2);

    let languages: Vec<_> = media
        .streams
        .iter()
        .filter_map(|stream| match stream {
            MediaStream::Audio(audio) => audio.info.language.as_deref(),
            _ => None,
        })
        .collect();
    assert_eq!(languages, vec!["eng", "jpn"]);

    assert_eq!(media.chapters[0].title.as_deref(), Some("Opening"));
    assert_eq!(media.chapters[1].title.as_deref(), Some("Closing"));
    assert!(media.chapters[0].start < media.chapters[0].end);
    assert!(media.chapters[1].start < media.chapters[1].end);
}

#[test]
fn reports_non_zero_start_time_for_mpegts() {
    let media = probe_fixture("sample.ts");

    let Some(start_time) = media.start_time else {
        panic!("expected a container start time");
    };
    assert!(
        start_time.micros() > 0,
        "expected a non-zero start time, got {start_time}"
    );
}

#[test]
fn reports_ffprobe_failure_with_path_and_stderr() {
    let path = fixture("not-media.bin");

    match ffprobe::probe(&path) {
        Err(ProbeError::Failed {
            path: failed_path,
            stderr,
            ..
        }) => {
            assert_eq!(failed_path, path);
            assert!(!stderr.is_empty(), "ffprobe failure should preserve stderr");
        }
        other => panic!("expected an ffprobe failure, got {other:?}"),
    }
}

#[test]
fn reports_missing_files_as_ffprobe_failures() {
    let path = fixture("does-not-exist.mp4");

    match ffprobe::probe(&path) {
        Err(ProbeError::Failed { stderr, .. }) => {
            assert!(!stderr.is_empty(), "ffprobe failure should preserve stderr");
        }
        other => panic!("expected an ffprobe failure, got {other:?}"),
    }
}

#[test]
fn application_probes_off_the_calling_thread() {
    let mut application = Application::new();
    application.open_media(fixture("sample.mp4"));

    let deadline = Instant::now() + Duration::from_secs(10);
    while Instant::now() < deadline {
        application.poll();
        if matches!(application.state(), OpenState::Ready) {
            break;
        }
        thread::sleep(Duration::from_millis(10));
    }

    assert!(
        matches!(application.state(), OpenState::Ready),
        "probe did not finish: {:?}",
        application.state()
    );
    let Some(media) = application.media() else {
        panic!("ready application should expose media");
    };
    assert!(media.format.name.contains("mp4"));
}
